draw((0.5,0.5)--(1.5,0.5)--(1.5,1.5)--(0.5,1.5)
--(0.5,0.5));
draw((1,0)--(2,0)--(2,1)--(1,1)--(1,0));

draw((-0.4,1)--(-0.4,2),Bars);
label("6",(-0.4,1.5),UnFill(1));

draw((0.5,1.5)--(0.5,2));
draw((0,1.5)--(0.5,1.5));

draw((1.5,0.5)--(2,0.5));
draw((1.5,0)--(1.5,0.5));

label("3",(0.25,2),N);
label("3",(0.75,2),N);

[/asy]

